function validate([nums1, nums2, k]) {
  if (nums1.length < 1 || nums1.length > 100000) return 'nums1 needs 1 to 100,000 values.';
  if (nums2.length !== nums1.length) return 'nums1 and nums2 have the same length.';
  if (nums1.some(v => v < 1 || v > 1000000) || nums2.some(v => v < 1 || v > 1000000)) return 'Every value is between 1 and 1,000,000.';
  if (k < 1 || k > nums1.length) return 'k is between 1 and n.';
  return null;
}

