function findMaxSum(nums1, nums2, k) {
  const n = nums1.length;
  const heap = [];

  function push(value) {
    heap.push(value);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent] <= heap[child]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  }

  function popSmallest() {
    const smallest = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return smallest;
    heap[0] = last;
    let parent = 0;
    while (true) {
      let child = 2 * parent + 1;
      if (child >= heap.length) break;
      if (child + 1 < heap.length && heap[child + 1] < heap[child]) child++;
      if (heap[parent] <= heap[child]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      parent = child;
    }
    return smallest;
  }

  const order = Array.from({ length: n }, (_, i) => i);
  order.sort((a, b) => nums1[a] - nums1[b]);
  const answer = new Array(n).fill(0);
  let sum = 0;
  for (let p = 0; p < n; p++) {
    const i = order[p];
    if (p > 0 && nums1[order[p - 1]] === nums1[i]) {
      answer[i] = answer[order[p - 1]];
    } else {
      answer[i] = sum;
    }
    push(nums2[i]);
    sum += nums2[i];
    if (heap.length > k) {
      sum -= popSmallest();
    }
  }
  return answer;
}

