function findMaxSum(nums1, nums2, k) {
  // For each index, gather the eligible nums2 values, sort them from largest down and add the first k.
  return nums1.map((value, i) => {
    const eligible = [];
    for (let j = 0; j < nums1.length; j++) if (nums1[j] < value) eligible.push(nums2[j]);
    eligible.sort((a, b) => b - a);
    return eligible.slice(0, k).reduce((total, v) => total + v, 0);
  });
}

