function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(1, 8);
  // A narrow range for nums1 makes many ties; the full range makes most values distinct.
  const top1 = rand() < 0.5 ? int(1, Math.max(1, n >> 1)) : 1000000;
  const top2 = rand() < 0.5 ? 10 : 1000000;
  const nums1 = Array.from({ length: n }, () => int(1, top1));
  const nums2 = Array.from({ length: n }, () => int(1, top2));
  // k = 1 and k = n are the extremes, so pick them often.
  const pick = rand();
  const k = pick < 0.2 ? 1 : pick < 0.4 ? n : int(1, n);
  return [nums1, nums2, k];
}
